/* ============ Admin panel ============ */
const AD={
 isAdmin(){return S.me.kind==='admin'},
 go(t){S.a.tab=t;S.a.preview=null;render();window.scrollTo(0,0)},
 preview(kind,id){S.a.preview=kind;S.a.asId=id||(kind==='driver'?D().drivers[0].id:D().customers.find(c=>c.login).id);if(kind==='driver'){S.d.scr='route';S.d.tab='route'}else{S.c.tab='home'}save();render()},
 NAV:[['home','grid','Overview'],['cust','users','Customers'],['route','route','Routes'],['drv','truck','Drivers'],['sup','chat','Support'],['rep','chart','Reports'],['set','sliders','Settings']],
 view(){const me=S.me;const tab=S.a.preview?'':S.a.tab;
  const side=`<aside class="side"><div style="padding:2px 8px 4px">${logo('full',66)}</div>
  <div class="nav">${AD.NAV.map(n=>`<button class="${tab===n[0]?'on':''}" onclick="AD.go('${n[0]}')">${ic(n[1])}${n[2]}</button>`).join('')}
  <span class="lbl">Preview the apps</span><button class="${S.a.preview==='driver'?'on':''}" onclick="AD.preview('driver')">${ic('phone')}Driver app</button><button class="${S.a.preview==='customer'?'on':''}" onclick="AD.preview('customer')">${ic('phone')}Customer app</button></div>
  <div class="me"><div class="row"><span class="avatar sm tint-acc">${initials(me.name)}</span><div class="grow"><b class="sm">${esc(me.name)}</b><div class="xs mute">${me.kind==='admin'?'Admin':'Support'}</div></div><button class="ib flat" onclick="toggleTheme()" aria-label="Theme">${ic(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="ib flat" onclick="signOut()" aria-label="Sign out">${ic('logout')}</button></div></div></aside>`;
  const mt=`<nav class="mtab">${[['home','grid','Overview'],['cust','users','Customers'],['route','route','Routes'],['sup','chat','Support'],['more','more','More']].map(n=>`<button class="${(tab===n[0]||(n[0]==='more'&&(['drv','rep','set'].includes(tab)||S.a.preview)))?'on':''}" onclick="AD.go('${n[0]}')" aria-label="${n[2]}">${ic(n[1])}<span>${n[2]}</span></button>`).join('')}</nav>`;
  let main;if(S.a.preview){main=AD.previewView()}else main=AD[tab]();if(!S.a.preview)main=`<div class="mlogo">${logobar(`${themeBtn()}<span class="avatar sm tint-acc">${initials(me.name)}</span>`)}</div>`+main;
  return `<div class="adm ${S.a.preview?'previewing':''}">${side}<main class="main ${S.a.preview?'center':''}">${main}${S.a.preview?'':powered()}</main>${mt}</div>`},
 previewView(){const k=S.a.preview;const list=k==='driver'?D().drivers:D().customers;const inner=k==='driver'?DR.view():CU.view();
  return `<div class="row sp wrap" style="width:100%;max-width:820px;margin-bottom:22px"><div class="row"><button class="ib" onclick="AD.go('home')" aria-label="Back">${ic('left')}</button><div><div class="sub">Previewing the ${k} app as</div><select class="in" style="padding:6px 36px 6px 10px;width:auto;font-weight:700;border:0;background-color:transparent" onchange="AD.preview('${k}',this.value)">${list.map(x=>`<option value="${x.id}" ${x.id===S.a.asId?'selected':''}>${esc(x.name)}${k==='customer'&&x.login?' (demo login)':''}</option>`).join('')}</select></div></div>
  <div class="row"><button class="btn sm g" onclick="AD.preview('${k==='driver'?'customer':'driver'}')">${ic('phone','s')} ${k==='driver'?'Customer':'Driver'} app</button><button class="btn sm g" onclick="AD.go('home')">Back to admin</button></div></div>
  ${phone(inner,k==='customer'&&S.c.ar?'rtl':'ltr')}
  <p class="sub mt16 c" style="max-width:520px">Live preview with the same data. Anything you do here, like confirming a stop or topping up, shows across the admin panel instantly.</p>`},
 head(title,sub,right){return `<div class="pagehead"><div><h1 class="title">${title}</h1>${sub?`<p class="sub mt4">${sub}</p>`:''}</div><div class="row wrap">${right||''}</div></div>`},
 todayStops(){return D().routes.filter(r=>r.date===TODAY_S).flatMap(r=>r.stops.map(s=>Object.assign({},s,{route:r})))},
 /* --- Overview --- */
 home(){const st=AD.todayStops(),del=st.filter(s=>s.status==='delivered'),miss=st.filter(s=>s.status==='missed'),low=D().customers.filter(c=>c.status==='active'&&bal(c.id)<=D().settings.lowAt).sort((a,b)=>bal(a.id)-bal(b.id)),open=openTickets();
  const m0=monthStart(),sold=D().ledger.filter(e=>e.kind==='topup'&&e.amount&&new Date(e.at)>=m0),rts=D().routes.filter(r=>r.date===TODAY_S);
  const feed=[...D().notes.slice(0,6).map(n=>({at:n.at,cls:n.kind==='ok'?'ok':n.kind==='bad'?'bad':n.kind==='top'?'top':'',txt:cust(n.cid).name+': '+n.body})),...D().audit.slice(0,4).map(a=>({at:a.at,cls:'',txt:a.who+' '+a.what.charAt(0).toLowerCase()+a.what.slice(1)}))].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,8);
  const onRoad=rts.filter(r=>r.stops.some(s=>s.status==='pending')).length;
  const routesBody=rts.map(r=>{const d=r.stops.filter(s=>s.status==='delivered').length,nx=r.stops.find(s=>s.status==='pending');return `<div class="li"><span class="avatar sm tint-mint">${initials(drv(r.driver).name)}</span><div class="grow"><div class="row sp"><b>${esc(drv(r.driver).name)}</b><span class="sub sm num">${d}/${r.stops.length}</span></div><div class="sub sm">${esc(r.name)}${nx?', next: '+esc(cust(nx.cid).name):', complete'}</div><div class="row mt8" style="gap:3px">${r.stops.map(s=>`<i style="flex:1;height:6px;border-radius:6px;background:${s.status==='delivered'?'var(--mint-i)':s.status==='missed'?'var(--rose-i)':nx&&s.id===nx.id?'var(--acc)':'var(--line)'}"></i>`).join('')}</div></div><button class="ib flat" onclick="AD.preview('driver','${r.driver}')" aria-label="Open driver app">${ic('phone')}</button></div>`}).join('')||'<div class="empty">No routes generated for today.</div>';
  const missBody=miss.map(s=>`<div class="li tap" onclick="AD.cdet('${s.cid}')"><span class="ic tint-rose">${ic('alert','s')}</span><div class="grow"><b>${esc(cust(s.cid).name)}</b><div class="sub sm">${hm(s.completed_at)}, ${esc(s.miss_reason)}</div></div>${ic('right','s')}</div>`).join('')||'<div class="empty">Nothing missed today.</div>';
  const lowBody=low.map(c=>`<div class="li tap" onclick="AD.cdet('${c.id}')"><span class="avatar sm tint-sand">${initials(c.name)}</span><div class="grow"><b>${esc(c.name)}</b><div class="sub sm">${zname(c)}</div></div><span class="pill tint-${bal(c.id)<=5?'rose':'sand'}">${bal(c.id)}</span></div>`).join('')||'<div class="empty">Everyone has enough coupons.</div>';
  const tkBody=open.slice(0,5).map(x=>`<div class="li tap" onclick="AD.tkt('${x.id}')"><div class="grow"><b>${esc(x.subject)}</b><div class="sub sm">${esc(cust(x.cid).name)}, ${rel(x.created_at)}</div></div><span class="pill tint-${x.status==='open'?'sand':'sky'}">${x.status.replace('_',' ')}</span></div>`).join('')||'<div class="empty">No open tickets.</div>';
  const feedBody=`<div class="feed">${feed.map(f=>`<div class="li ${f.cls}"><div class="grow"><div class="sm">${esc(f.txt)}</div><div class="xs mute">${rel(f.at)}</div></div></div>`).join('')}</div>`;
  return AD.head('Overview',fmtLong(TODAY),`<button class="btn g" onclick="AD.go('route')">${ic('route','s')} Routes</button><button class="btn p" onclick="AD.newCust()">${ic('plus','s')} New customer</button>`)+
  `<div class="kpis"><div class="kpi"><span class="ki tint-mint">${ic('check','s')}</span><div class="v num">${del.length}<span class="mute" style="font-size:18px;font-weight:600">/${st.length}</span></div><div class="l">Delivered</div></div><div class="kpi"><span class="ki tint-rose">${ic('alert','s')}</span><div class="v num" style="color:${miss.length?'var(--rose-i)':'inherit'}">${miss.length}</div><div class="l">Missed</div></div><div class="kpi"><span class="ki tint-sand">${ic('ticket','s')}</span><div class="v num" style="color:${low.length?'var(--sand-i)':'inherit'}">${low.length}</div><div class="l">Low coupons</div></div><div class="kpi"><span class="ki tint-sky">${ic('chat','s')}</span><div class="v num">${open.length}</div><div class="l">Tickets</div></div></div>
  <div class="kpis"><div class="kpi"><span class="ki tint-mint">${ic('card','s')}</span><div class="v num">${sum(sold,e=>e.coupons)}</div><div class="l">Coupons sold</div></div><div class="kpi"><span class="ki tint-mint">${ic('card','s')}</span><div class="v num">${kfmt(sum(sold,e=>e.amount))}</div><div class="l">Revenue ${D().settings.currency}</div></div><div class="kpi"><span class="ki tint-sky">${ic('drop','s')}</span><div class="v num">${-sum(D().ledger.filter(e=>e.kind==='delivered'&&new Date(e.at)>=m0),e=>e.coupons)}</div><div class="l">Bottles</div></div><div class="kpi"><span class="ki tint-lilac">${ic('users','s')}</span><div class="v num">${D().customers.filter(c=>c.status==='active').length}</div><div class="l">Customers</div></div></div>
  <div class="accs">
  ${MAPS.ok()?acc('a-map',6,'Live map',onRoad?onRoad+' driver'+(onRoad>1?'s':'')+' on the road':'All routes complete','',`<div class="mapwrap lg"><div class="lmap" data-kind="admin"></div></div>`,{flush:true}):''}
  ${acc('a-routes',0,'Routes today',rts.length?del.length+' of '+st.length+' delivered':'Not generated yet',rts.length,routesBody)}
  ${acc('a-miss',2,'Missed today',miss.length?'Needs a call or reschedule':'Nothing missed',miss.length,missBody)}
  ${acc('a-low',5,'Low on coupons',D().settings.lowAt+' or fewer left',low.length,lowBody)}
  ${acc('a-tk',4,'Open tickets',open.length?rel(open[0].created_at)+' latest':'All answered',open.length,tkBody)}
  ${(()=>{const o=D().customers.filter(c=>c.status==='active'&&!routeOf(c));return o.length?acc('a-out',0,'Out of delivery zone','Not on any route',o.length,o.map(c=>`<div class="li tap" onclick="AD.cdet('${c.id}')"><span class="zb num">${c.qzone||'?'}</span><div class="grow"><b>${esc(c.name)}</b><div class="sub sm">${esc(coverage(c.qzone).why)}</div></div>${ic('right','s')}</div>`).join(''),{cls:'kx'}):''})()}
  ${acc('a-feed',3,'Recent activity',feed.length?rel(feed[0].at):'Nothing yet','',feedBody)}
  </div>`},
 /* --- Customers --- */
 custFiltered(){const f=S.a.f;return D().customers.filter(c=>(f.z==='All'||(f.z==='Out of zone'?!routeOf(c):(routeOf(c)||{}).code===f.z))&&(f.c==='All'||status(c)[1]===f.c||(f.c==='Paused'&&c.status==='paused'))&&(c.name+' '+c.no+' '+c.phone+' '+(c.email||'')).toLowerCase().includes(f.q.toLowerCase())).sort((a,b)=>a.no-b.no)},
 cust(){const zs=['All',...D().rdefs.map(r=>r.code),'Out of zone'],l=AD.custFiltered();
  return AD.head('Customers',D().customers.length+' customers, '+D().customers.filter(c=>c.status==='active').length+' active',`<button class="btn g" onclick="AD.csv('customers')">${ic('download','s')} Export</button><button class="btn p" onclick="AD.newCust()">${ic('plus','s')} New customer</button>`)+
  `<div class="search mb12">${ic('search')}<input class="in" placeholder="Search by name, ID, phone or email" value="${esc(S.a.f.q)}" oninput="S.a.f.q=this.value;AD.custList()"></div>
  <div class="chips mb8">${zs.map(z=>`<button class="chip ${S.a.f.z===z?'on':''}" onclick="S.a.f.z='${z}';render()">${z}</button>`).join('')}</div>
  <div class="chips mb12">${['All','Healthy','Running low','Low','Paused'].map(z=>`<button class="chip ${S.a.f.c===z?'on':''}" onclick="S.a.f.c='${z}';render()">${z}</button>`).join('')}</div>
  <div class="folds" id="clist">${AD.custFolders(l)}</div>`},
 custList(){const el=$('#clist');if(el)el.innerHTML=AD.custFolders(AD.custFiltered())},
 custFolders(l){if(!l.length)return '<div class="card empty" style="grid-column:1/-1">No customers match</div>';
  return l.map((c,i)=>{const [tone,lab]=status(c),b=bal(c.id),off=c.status!=='active';return fold(i,`AD.cdet('${c.id}')`,initials(c.name),esc(c.name),`${routeOf(c)?routeOf(c).code+', ':''}${zname(c)}, ${DAYS[c.weekday].slice(0,3)} ${c.ws}`,`<span class="fr"><b class="num">${ic('ticket','s')}${b}</b><em class="${off?'':!routeOf(c)||tone==='rose'?'hot':tone==='sand'?'warm':''}">${off?c.status:!routeOf(c)?'Out of zone':lab}</em></span>`)}).join('')},
 cdet(id){const c=cust(id),[tone,lab]=status(c),h=ledgerOf(id).slice(0,6),nd=nextDelivery(c),dr=driverFor(c),hold=nextHold(c),tk=D().tickets.filter(t=>t.cid===id&&t.status!=='resolved');
  sheet(`<div class="row sp"><div class="row"><span class="avatar tint-sky">${initials(c.name)}</span><div><h2 class="title" style="font-size:22px">${esc(c.name)}</h2><div class="sub">Customer ${c.no}, since ${fmtDay(c.since)}</div></div></div><button class="ib flat" onclick="closeSheet()" aria-label="Close">${ic('x')}</button></div>
  <div class="stat3 mt16"><div class="tint-${tone}"><b class="num">${bal(id)}</b><span>coupons left, ${lab.toLowerCase()}</span></div><div class="tint-grey"><b class="num">${avgMonthly(id)}</b><span>used per month</span></div><div class="tint-grey"><b class="num">${daysLeft(id)??'—'}</b><span>days of cover</span></div></div>
  <div class="card mt12 tight"><div class="li"><span class="grow mute">Phone</span><b>${esc(c.phone)}</b></div>${c.email?`<div class="li"><span class="grow mute">Email</span><b>${esc(c.email)}</b></div>`:''}<div class="li"><span class="grow mute">Address</span><div class="plate-row">${plate(c,{size:'sm'})}<b style="text-align:end">${esc(c.building)}<div class="sub sm" style="font-weight:500">${esc(c.street)}</div></b></div></div><div class="li"><span class="grow mute">Delivery</span><b>${DAYS[c.weekday]}s, ${c.ws} – ${c.we}, ${c.bottles} bottles</b></div><div class="li"><span class="grow mute">Next</span><b>${nd.date?fmtD(nd.date):'—'}${nd.moved?' (moved)':''}${hold?', hold '+fmtDay(hold.start)+' – '+fmtDay(hold.end):''}</b></div><div class="li"><span class="grow mute">Route</span>${routeOf(c)?`<b>${routeOf(c).code} ${esc(routeOf(c).name)}, ${esc(dr.name.split(' ')[0])}</b>`:`<b style="color:var(--rose-i)">Out of delivery zone, ${esc(coverage(c.qzone).why)}</b>`}</div><div class="li"><span class="grow mute">Empties with customer</span><b class="num">${c.empties}</b></div>${c.gate?`<div class="li"><span class="grow mute">Gate note</span><b>${esc(c.gate)}</b></div>`:''}</div>
  ${tk.length?`<div class="card tint-sand row" style="padding:12px 14px">${ic('chat')}<div class="grow sm"><b>${tk.length} open ticket${tk.length>1?'s':''}:</b> ${esc(tk[0].subject)}</div><button class="btn sm" style="background:var(--ink);color:var(--bg)" onclick="AD.tkt('${tk[0].id}')">Open</button></div>`:''}
  <div class="card tight"><div class="li" style="padding-bottom:6px"><b>Recent activity</b></div>${h.map(e=>`<div class="li"><div class="grow"><span>${e.kind==='delivered'?'Delivered '+e.bottles:e.kind==='missed'?'Missed':e.adjust?'Adjusted':'Top-up'}</span><div class="sub xs">${fmtD(e.at)}, ${hm(e.at)}${e.ref?', ref '+e.ref:e.detail?', '+esc(e.detail):''}</div></div><b class="num" style="color:${e.coupons>0?'var(--mint-i)':e.coupons<0?'var(--acc-i)':'var(--mute)'}">${e.coupons>0?'+':''}${e.coupons||'—'}</b></div>`).join('')}</div>
  <div class="two"><button class="btn t" onclick="AD.editCust('${id}')">${ic('edit','s')} Edit details</button>${AD.isAdmin()?`<button class="btn t" onclick="AD.adjust('${id}')">${ic('ticket','s')} Adjust coupons</button>`:`<button class="btn g" disabled>Adjust coupons (admin)</button>`}</div>
  <div class="two mt8"><a class="btn g" href="tel:${c.phone.replace(/\s/g,'')}">${ic('phone','s')} Call</a><a class="btn g" href="https://wa.me/${c.phone.replace(/\D/g,'')}" target="_blank" rel="noopener">${ic('wa','s')} WhatsApp</a></div>
  ${c.login?`<button class="btn o w mt8" onclick="closeSheet();AD.preview('customer','${id}')">${ic('phone','s')} Open their customer app</button>`:''}`)},
 adjust(id){const c=cust(id);sheet(`<h2 class="title" style="font-size:22px">Adjust coupons</h2><p class="sub mt4">${esc(c.name)} has ${bal(id)} coupons. Every change is written to the ledger with your name.</p>
  <label class="field"><span>Coupons to add (use a minus to remove)</span><input class="in" id="ad" type="number" value="60" inputmode="numeric"></label><label class="field"><span>Reason</span><select class="in" id="an"><option>Cash payment at office</option><option>Bank transfer received</option><option>Goodwill for missed delivery</option><option>Correction</option><option>Promotion</option></select></label>
  <div class="two mt16"><button class="btn g" onclick="AD.cdet('${id}')">Cancel</button><button class="btn p" onclick="(function(){const d=parseInt($('#ad').value);if(!d)return toast('Enter a number other than 0');ACT.adjust('${id}',d,$('#an').value);toast('Coupons updated, now '+bal('${id}'));AD.cdet('${id}');render()})()">Save</button></div>`)},
 editCust(id){const c=cust(id);sheet(`<div class="row sp"><h2 class="title" style="font-size:22px">Edit customer</h2><span class="sub">ID ${c.no}</span></div>
  <div class="two" style="grid-template-columns:110px 1fr"><label class="field"><span>Title</span><select class="in" id="eti">${['','Mr.','Ms.'].map(x=>`<option value="${x}" ${(c.title||'')===x?'selected':''}>${x||'None'}</option>`).join('')}</select></label><label class="field"><span>Full name</span><input class="in" id="en" value="${esc(c.name)}"></label></div><div class="two"><label class="field"><span>Mobile (locked)</span><input class="in" value="${esc(c.phone)}" disabled></label><label class="field"><span>Email</span><input class="in" id="ee" type="email" value="${esc(c.email||'')}"></label></div>
  <div class="two"><label class="field"><span>Status</span><select class="in" id="es">${['active','paused','closed'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field"><span>Area</span><select class="in" id="ez">${D().zones.map(z=>`<option value="${z.id}" ${c.zone===z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></label></div>
  <div class="field"><span>Blue plate</span>${plate(c,{edit:true,id:'eqp'})}</div>
  <label class="field"><span>Villa or building</span><input class="in" id="eb" value="${esc(c.building)}"></label><label class="field"><span>Street and area</span><input class="in" id="et" value="${esc(c.street)}"></label><label class="field"><span>Gate note for the driver</span><input class="in" id="eg" value="${esc(c.gate)}"></label>
  <label class="field"><span>Map pin (paste a Google Maps link or "lat, lng")</span><input class="in" id="el" placeholder="${c.lat}, ${c.lng}"></label>
  <div class="two"><label class="field"><span>Delivery day</span><select class="in" id="ed">${DAYS.map((d,i)=>`<option value="${i}" ${c.weekday===i?'selected':''}>${d}</option>`).join('')}</select></label><label class="field"><span>Bottles per delivery</span><input class="in" id="eq" type="number" min="1" value="${c.bottles}"></label></div>
  <div class="two"><label class="field"><span>Window from</span><input class="in" id="ew" type="time" value="${c.ws}"></label><label class="field"><span>Window to</span><input class="in" id="ex" type="time" value="${c.we}"></label></div>
  <div class="two mt16"><button class="btn g" onclick="AD.cdet('${id}')">Cancel</button><button class="btn p" onclick="AD.saveCust('${id}')">Save changes</button></div>`)},
 parsePin(t){try{t=decodeURIComponent(t.trim())}catch(e){t=t.trim()}if(!t)return null;const m=t.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/)||t.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/)||t.match(/[?&](?:q|ll|query)=(-?\d+\.\d+),(-?\d+\.\d+)/)||t.match(/^(-?\d+\.?\d*)[ ,]+(-?\d+\.?\d*)$/);return m?[+m[1],+m[2]]:false},
 saveCust(id){const c=cust(id);const v=i=>$('#'+i).value.trim();if(!v('en'))return toast('Name is required');const pin=AD.parsePin(v('el'));if(pin===false)return toast('Map pin not understood. Paste a Google Maps link or "25.26, 51.45".');
  Object.assign(c,{title:v('eti'),name:v('en'),email:v('ee')||'',status:v('es'),zone:v('ez'),building:v('eb'),street:v('et'),gate:v('eg'),weekday:+v('ed'),bottles:clamp(+v('eq')||c.bottles,1,20),ws:v('ew')||c.ws,we:v('ex')||c.we});if(pin){c.lat=pin[0];c.lng=pin[1]}const q=plateRead('eqp');if(q.qbuilding&&q.qstreet&&q.qzone)Object.assign(c,q);
  audit('Edited customer '+c.name);save();toast(routeOf(c)?'Saved, '+routeOf(c).code:'Saved. Out of delivery zone, not routed');AD.cdet(id);render()},
 _last:{d:TODAY.getDay(),w:'07:00',x:'09:00',q:3},
 newCust(){const L=AD._last;sheet(`<h2 class="title" style="font-size:22px">New customer</h2><p class="sub mt4">They sign in with this mobile number. Opening coupons are added to the ledger.</p>
  <div class="two" style="grid-template-columns:110px 1fr"><label class="field"><span>Title</span><select class="in" id="cti">${['','Mr.','Ms.'].map(x=>`<option value="${x}" ${('Mr.')===x?'selected':''}>${x||'None'}</option>`).join('')}</select></label><label class="field"><span>Full name</span><input class="in" id="cn" placeholder="e.g. Salem Al-Kubaisi"></label></div><label class="field"><span>Mobile number</span><input class="in" id="cp" type="tel" placeholder="5555 1234" oninput="AD.chkPhone(this.value)"><div class="xs mt4" id="pwarn" style="color:var(--rose-i);min-height:16px"></div></label>
  <label class="field" style="margin-top:0"><span>Email (optional)</span><input class="in" id="ce" type="email"></label>
  <div class="field"><span>Blue plate</span>${plate({},{edit:true,id:'nqp'})}</div>
  <div class="two"><label class="field"><span>Villa or building</span><input class="in" id="cb"></label><label class="field"><span>Street and area</span><input class="in" id="cs"></label></div>
  <label class="field"><span>Area</span><select class="in" id="cz">${D().zones.map(z=>`<option value="${z.id}">${esc(z.name)}</option>`).join('')}</select></label>
  <label class="field"><span>Map pin (Google Maps link or "lat, lng", optional)</span><input class="in" id="cl2"></label><label class="field"><span>Gate note (optional)</span><input class="in" id="cg"></label>
  <div class="two"><label class="field"><span>Delivery day</span><select class="in" id="cd">${DAYS.map((d,i)=>`<option value="${i}" ${i===L.d?'selected':''}>${d}</option>`).join('')}</select></label><label class="field"><span>Bottles per delivery</span><input class="in" id="cq" type="number" min="1" value="${L.q}"></label></div>
  <div class="two"><label class="field"><span>Window from</span><input class="in" id="cw" type="time" value="${L.w}"></label><label class="field"><span>Window to</span><input class="in" id="cx" type="time" value="${L.x}"></label></div>
  <label class="field"><span>Opening coupons</span><select class="in" id="cc"><option value="0">0, pay later</option>${D().packs.map(p=>`<option value="${p.id}">${p.coupons} coupons, ${money(p.price)} paid</option>`).join('')}</select></label>
  <button class="btn p w lg mt16" onclick="AD.saveNew(false)">Create customer</button><button class="btn g w mt8" onclick="AD.saveNew(true)">Create and add another</button>`,{focus:true})},
 norm(p){p=p.replace(/[^\d+]/g,'');if(p.startsWith('00'))p='+'+p.slice(2);if(!p.startsWith('+'))p=p.length===8?'+974'+p:'+'+p;return p.replace(/^(\+974)(\d{4})(\d{4})$/,'$1 $2 $3')},
 chkPhone(v){const el=$('#pwarn');if(!el)return;if(v.replace(/\D/g,'').length<8){el.textContent='';return}const p=AD.norm(v);const ex=D().customers.find(c=>c.phone.replace(/\s/g,'')===p.replace(/\s/g,''));el.textContent=ex?'Already a customer: '+ex.name:''},
 saveNew(another){const v=i=>$('#'+i).value.trim();if(!v('cn')||v('cp').replace(/\D/g,'').length<8)return toast('Name and a valid mobile number are required');const p=AD.norm(v('cp'));if(D().customers.some(c=>c.phone.replace(/\s/g,'')===p.replace(/\s/g,'')))return toast('That number already belongs to a customer');
  const pin=AD.parsePin(v('cl2'));if(pin===false)return toast('Map pin not understood');const z=zone(v('cz'));AD._last={d:+v('cd'),w:v('cw'),x:v('cx'),q:+v('cq')||3};
  const c={id:'c'+uid(),no:Math.max(...D().customers.map(c=>c.no))+1,title:v('cti'),name:v('cn'),email:v('ce'),phone:p,building:v('cb'),street:v('cs'),zone:z.id,lat:pin?pin[0]:+(z.lat+(Math.random()-.5)*.02).toFixed(5),lng:pin?pin[1]:+(z.lng+(Math.random()-.5)*.02).toFixed(5),gate:v('cg'),weekday:AD._last.d,ws:AD._last.w,we:AD._last.x,bottles:AD._last.q,login:false,status:'active',holds:[],resched:null,emailSaved:!!v('ce'),lang:'en',notif:{wa:true,email:true},empties:0,since:TODAY_S,target:0};Object.assign(c,plateRead('nqp'));if(!c.qzone)c.qzone=QZONES[z.id];
  D().customers.push(c);const pk=v('cc');if(pk!=='0'){const P=D().packs.find(p=>p.id===pk);D().ledger.push({id:uid(),cid:c.id,kind:'topup',at:new Date().toISOString(),coupons:P.coupons,amount:P.price,detail:'Opening pack, paid at sign-up',pack:P.id})}
  audit('Created customer '+c.name);save();toast(routeOf(c)?'Customer created, '+routeOf(c).code:'Created. Zone '+c.qzone+' is out of delivery zone, not routed');if(another)AD.newCust();else closeSheet();render()},
 /* --- Drivers --- */
 drv(){return AD.head('Drivers',D().drivers.filter(d=>d.active).length+' active',AD.isAdmin()?`<button class="btn p" onclick="AD.newDrv()">${ic('plus','s')} New driver</button>`:'')+
  `<div class="cols">${D().drivers.map(d=>{const r=D().routes.find(r=>r.date===TODAY_S&&r.driver===d.id),st=r?r.stops:[],done=st.filter(s=>s.status==='delivered').length,m=D().ledger.filter(e=>e.kind==='delivered'&&e.driver===d.id&&new Date(e.at)>=monthStart());
  return `<div class="card"><div class="row sp"><div class="row"><span class="avatar tint-mint">${initials(d.name)}</span><div><b class="h3">${esc(d.name)}</b><div class="sub sm">${esc(d.vehicle)}, plate ${esc(d.plate)}, ${esc(d.phone)}</div></div></div><span class="pill tint-${d.active?'mint':'grey'}">${d.active?'Active':'Inactive'}</span></div>
  <div class="row mt12 wrap" style="gap:6px">${drvRoutes(d.id).map(r=>`<span class="pill tint-grey"><b>${r.code}</b> ${esc(r.name)}</span>`).join('')||'<span class="sub sm">No routes</span>'}</div>
  <div class="row sp mt16"><span class="sub sm">Today</span><b class="num sm">${done} of ${st.length} stops</b></div><div class="bar mint mt4"><i style="width:${st.length?done/st.length*100:0}%"></i></div>
  <div class="stat3 mt12"><div class="tint-grey"><b class="num">${m.length}</b><span>deliveries this month</span></div><div class="tint-grey"><b class="num">${-sum(m,e=>e.coupons)}</b><span>bottles this month</span></div><div class="tint-grey"><b class="num">${D().customers.filter(c=>c.status==='active'&&(routeOf(c)||{}).driver===d.id).length}</b><span>customers covered</span></div></div>
  <div class="two mt12"><button class="btn t" onclick="AD.preview('driver','${d.id}')">${ic('phone','s')} Open driver app</button>${AD.isAdmin()?`<button class="btn g" onclick="AD.editDrv('${d.id}')">${ic('edit','s')} Edit</button>`:`<a class="btn g" href="tel:${d.phone.replace(/\s/g,'')}">${ic('phone','s')} Call</a>`}</div></div>`}).join('')}</div>`},
 newDrv(){sheet(`<h2 class="title" style="font-size:22px">New driver</h2><p class="sub mt4">Creates their sign-in and driver profile. Give them the email and password.</p>
  <label class="field"><span>Full name</span><input class="in" id="dn"></label><label class="field"><span>Email (used to sign in)</span><input class="in" id="de" type="email"></label><label class="field"><span>Temporary password</span><input class="in" id="dp" value="0000"></label>
  <div class="two"><label class="field"><span>Mobile</span><input class="in" id="dm" type="tel"></label><label class="field"><span>Vehicle</span><input class="in" id="dv" placeholder="Van 3"></label></div>
  <div class="field"><span>Routes</span><div class="row wrap" style="gap:6px">${D().rdefs.map(r=>`<label class="chip" style="cursor:pointer"><input type="checkbox" value="${r.code}" class="dz"  style="margin:0 2px 0 0">${r.code} ${esc(r.name)}</label>`).join('')}</div></div>
  <button class="btn p w lg mt16" onclick="(function(){const v=i=>$('#'+i).value.trim();if(!v('dn')||!v('de'))return toast('Name and email are required');const zs=$$('.dz:checked').map(x=>x.value);const d={id:'d'+uid(),name:v('dn'),email:v('de'),phone:v('dm')?AD.norm(v('dm')):'',vehicle:v('dv')||'Van',plate:'',active:true,zones:[]};D().drivers.push(d);D().rdefs.forEach(r=>{if(zs.includes(r.code))r.driver=d.id});audit('Created driver '+d.name);save();closeSheet();render();toast('Driver created. They can sign in now.')})()">Create driver</button>`,{focus:true})},
 editDrv(id){const d=drv(id);sheet(`<h2 class="title" style="font-size:22px">Edit driver</h2>
  <label class="field"><span>Full name</span><input class="in" id="dn" value="${esc(d.name)}"></label><div class="two"><label class="field"><span>Mobile</span><input class="in" id="dm" value="${esc(d.phone)}"></label><label class="field"><span>Vehicle</span><input class="in" id="dv" value="${esc(d.vehicle)}"></label></div>
  <div class="field"><span>Routes</span><div class="row wrap" style="gap:6px">${D().rdefs.map(r=>`<label class="chip" style="cursor:pointer"><input type="checkbox" value="${r.code}" class="dz" ${r.driver===d.id?'checked':''} style="margin:0 2px 0 0">${r.code} ${esc(r.name)}</label>`).join('')}</div></div>
  <div class="li mt12" style="border-top:0"><span class="grow b">Active (can sign in and receive routes)</span><button class="sw ${d.active?'on':''}" id="dact" onclick="this.classList.toggle('on')"></button></div>
  <div class="two mt12"><button class="btn g" onclick="closeSheet()">Cancel</button><button class="btn p" onclick="(function(){const v=i=>$('#'+i).value.trim();const d=drv('${id}');d.name=v('dn')||d.name;d.phone=v('dm');d.vehicle=v('dv');const rc=$$('.dz:checked').map(x=>x.value);D().rdefs.forEach(r=>{if(rc.includes(r.code))r.driver=d.id;else if(r.driver===d.id)r.driver=null});d.active=$('#dact').classList.contains('on');audit('Edited driver '+d.name);save();closeSheet();render();toast('Saved')})()">Save</button></div>`)},
 /* --- Routes --- */
 route(){const rs=D().routes.filter(r=>r.date===S.a.rdate);const d=parseYmd(S.a.rdate),wd=d.getDay();
  const dueC=D().customers.filter(c=>c.status==='active'&&c.weekday===wd&&!onHold(c,S.a.rdate)),due=dueC.filter(c=>routeOf(c)).length,outDue=dueC.filter(c=>!routeOf(c));
  const stops=rs.flatMap(r=>r.stops.map(s=>({s,r}))),by={};stops.forEach(x=>{const rd=routeOf(cust(x.s.cid));const k=rd?rd.code:'OUT';(by[k]=by[k]||[]).push(x)});
  const H=housesByZone(),out=D().customers.filter(c=>c.status==='active'&&!routeOf(c));
  const body=rd=>{const L=(by[rd.code]||[]).sort((a,b)=>a.s.seq-b.s.seq);
   return `<div class="row sp" style="padding:6px 0 10px;border-bottom:1px solid var(--line2);gap:8px"><div class="row" style="min-width:0;gap:8px"><span class="avatar sm tint-mint">${rd.driver?initials(drv(rd.driver).name):'?'}</span><select class="in" style="width:auto;padding:7px 34px 7px 12px" onchange="AD.setRouteDriver('${rd.code}',this.value)"><option value="" ${rd.driver?'':'selected'}>No driver</option>${D().drivers.map(x=>`<option value="${x.id}" ${x.id===rd.driver?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${rd.driver?`<button class="ib flat" onclick="AD.preview('driver','${rd.driver}')" aria-label="Open driver app">${ic('phone')}</button>`:''}</div>
   <div class="row wrap" style="gap:4px;padding:10px 0 4px">${rd.zones.map(z=>`<span class="zb num" title="${(H[z]||{houses:0}).houses} houses">${z}</span>`).join('')}</div>
   ${L.length&&MAPS.ok()?`<div class="mapwrap" style="margin:8px 0 6px"><div class="lmap" data-kind="rz" data-code="${rd.code}"></div></div>`:''}
   ${L.length?(()=>{const run=L[0].r,o=run.opt,busy=S.a.optBusy===rd.code;return `<div class="row sp wrap" style="gap:8px;padding:4px 0 8px"><div class="sub sm" style="min-width:0">${o?`Optimised ${hm(new Date(o.at))}: ${o.km.toFixed(1)} km, ${ORS.dur(o.min)} driving${o.tw?'':', time slots ignored'}`:'Order not optimised yet'}</div><button class="btn sm ${o?'g':'p'}" ${busy?'disabled':''} onclick="ORS.optimise('${rd.code}')">${ic('route','s')} ${busy?'Optimising…':o?'Optimise again':'Optimise order'}</button></div>`})():''}
   ${L.map(({s})=>{const c=cust(s.cid);return `<div class="li tap" onclick="${s.status==='pending'?`AD.cdet('${c.id}')`:`AD.stopDet('${s.id}')`}"><span class="num" style="width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:13px;flex:none;background:${s.status==='delivered'?'var(--mint)':s.status==='missed'?'var(--rose)':'var(--card2)'};color:${s.status==='delivered'?'var(--mint-i)':s.status==='missed'?'var(--rose-i)':'var(--ink)'}">${s.seq}</span><div class="grow" style="min-width:0"><b class="ell" style="display:block">${esc(c.name)}</b><div class="sub sm ell">${s.status==='pending'&&s.eta!=null?'<b style="color:var(--acc)">ETA '+ORS.hm(s.eta)+'</b>, ':''}Z${c.qzone} St ${c.qstreet} Bldg ${c.qbuilding}, ${c.ws}${s.status==='missed'?', '+esc(s.miss_reason):''}</div></div><span class="rq num">${ic('drop','s')}${s.status==='delivered'?s.delivered:s.planned}</span><span class="pill tint-${s.status==='delivered'?'mint':s.status==='missed'?'rose':'sky'}">${s.status==='pending'?'to do':s.status}</span></div>`}).join('')||'<div class="empty">No stops on this date.</div>'}`};
  const outBody=`<p class="sub sm" style="padding:8px 0 4px">Zone is outside R01 to R06 or in the exclusion list. These customers are never put on a route.</p>${out.map(c=>{const v=coverage(c.qzone);return `<div class="li tap" onclick="AD.cdet('${c.id}')"><span class="zb num">${c.qzone||'?'}</span><div class="grow" style="min-width:0"><b class="ell" style="display:block">${esc(c.name)}</b><div class="sub sm ell">${esc(v.why)}${c.weekday===wd?', due this day':''}</div></div>${ic('right','s')}</div>`}).join('')||'<div class="empty">Every active customer is inside a route.</div>'}`;
  return AD.head('Routes',fmtLong(d),`<button class="btn g" onclick="AD.go('drv')">${ic('truck','s')} Drivers</button><button class="btn g" onclick="AD.combine()">${ic('grid','s')} Edit routes</button>`)+
  `<div class="card"><div class="row wrap" style="gap:8px;align-items:center"><input class="in" type="date" value="${S.a.rdate}" onchange="S.a.rdate=this.value;render()" style="width:auto;padding:9px 12px" aria-label="Date"><button class="btn sm g" onclick="S.a.rdate='${TODAY_S}';render()">Today</button><button class="btn sm g" onclick="S.a.rdate='${ymd(addDays(d,1))}';render()">Next day</button><span class="grow"></span><button class="btn p" onclick="(function(){const n=ACT.generate(S.a.rdate);toast(n?n+' stops added':'Routes are already up to date');render()})()">${ic('route','s')} Generate</button></div>
  <div class="row mt12 wrap" style="gap:16px"><span class="rq num">${ic('users','s')}${due} due</span><span class="rq num">${ic('check','s')}${stops.filter(x=>x.s.status==='delivered').length}/${stops.length} done</span><span class="rq num">${ic('drop','s')}${sum(stops,x=>x.s.planned)} bottles</span>${outDue.length?`<span class="rq num" style="color:var(--rose-i)">${ic('alert','s')}${outDue.length} out of zone</span>`:''}</div></div>
  <div class="accs">${D().rdefs.map((rd,i)=>{const L=by[rd.code]||[],done=L.filter(x=>x.s.status==='delivered').length,mi=L.filter(x=>x.s.status==='missed').length;
   return acc('rz-'+rd.code,i,`<span class="rcode">${rd.code}</span>${esc(rd.name)}`,`${rd.driver?esc(drv(rd.driver).name.split(' ')[0]):'No driver'}, ${L.length?done+'/'+L.length+' done':'no stops'}${mi?', '+mi+' missed':''}`,`${sum(L,x=>x.s.planned)}<small>/${L.length}</small>`,body(rd),{group:'rz-'})}).join('')}
  ${acc('rz-OUT',0,'Out of delivery zone',out.length?out.length+' customer'+(out.length>1?'s':'')+' not covered':'None',out.length,outBody,{group:'rz-',cls:'kx'})}</div>`},
 setRouteDriver(code,v){const rd=D().rdefs.find(r=>r.code===code),old=rd.driver;rd.driver=v||null;let moved=0;
  if(v&&old!==v){D().routes.filter(r=>r.date>=TODAY_S&&r.driver!==v).forEach(r=>{const mv=r.stops.filter(s=>s.status==='pending'&&(routeOf(cust(s.cid))||{}).code===code);if(!mv.length)return;r.stops=r.stops.filter(s=>!mv.includes(s));let t=D().routes.find(x=>x.date===r.date&&x.driver===v);if(!t){t={id:'r_'+v+'_'+r.date,date:r.date,name:'',driver:v,stops:[]};D().routes.push(t)}mv.forEach(s=>{s.seq=t.stops.length+1;t.stops.push(s);moved++})})}
  D().routes.forEach(r=>{r.name=runName(r.driver);r.stops.sort((a,b)=>a.seq-b.seq).forEach((s,i)=>s.seq=i+1)});D().routes=D().routes.filter(r=>r.stops.length);
  audit(code+' assigned to '+(v?drv(v).name:'no driver'));save();toast(code+(v?' now with '+drv(v).name.split(' ')[0]:' has no driver')+(moved?', '+moved+' stops moved':''));if($('#dim'))AD.combine();else render()},
 combine(){const H=housesByZone(),R=D().rdefs,known=new Set([...R.flatMap(r=>r.zones),...D().excl.flatMap(e=>e.zones)]);
  const unk=Object.keys(H).map(Number).filter(z=>!known.has(z));
  const zb=z=>`<button class="zb2 num" onclick="AD.zoneMenu(${z})" aria-label="Zone ${z}">${z}${H[z]?`<small>${H[z].houses}</small>`:''}</button>`;
  sheet(`<div class="row sp"><h2 class="title" style="font-size:22px">Delivery routes</h2><button class="ib flat" onclick="closeSheet(render)" aria-label="Close">${ic('x')}</button></div>
  <p class="sub sm mt4">Official zone numbers from the blue plates. Small number = unique houses (zone, street, building). Tap a zone to move it.</p>
  ${R.map((rd,i)=>{const hs=sum(rd.zones,z=>H[z]?H[z].houses:0),cs=sum(rd.zones,z=>H[z]?H[z].cust:0);return `<div class="rcard k${i%7}"><div class="row sp"><b><span class="rcode">${rd.code}</span>${esc(rd.name)}</b><span class="rq num">${ic('home','s')}${hs}</span></div>
   <div class="row wrap" style="gap:5px;margin:10px 0">${rd.zones.map(zb).join('')}</div>
   <div class="row" style="gap:8px"><span class="sub xs grow">${cs} customers</span><select class="in" style="width:auto;padding:6px 32px 6px 10px;font-size:13px" onchange="AD.setRouteDriver('${rd.code}',this.value)"><option value="" ${rd.driver?'':'selected'}>No driver</option>${D().drivers.map(x=>`<option value="${x.id}" ${x.id===rd.driver?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div>`}).join('')}
  <div class="h3" style="padding:8px 4px 0">Not covered</div>
  <div class="card tight mt8">${D().excl.map(e=>`<div class="li" style="flex-wrap:wrap"><b class="sm grow">${esc(e.label)}</b><div class="row wrap" style="gap:5px">${e.zones.map(zb).join('')}</div></div>`).join('')}
  ${unk.length?`<div class="li" style="flex-wrap:wrap"><b class="sm grow" style="color:var(--rose-i)">Not in any list</b><div class="row wrap" style="gap:5px">${unk.map(zb).join('')}</div></div>`:''}</div>
  <div class="row mt12" style="gap:8px"><input class="in" id="nz" inputmode="numeric" placeholder="Zone number" style="width:120px"><button class="btn g grow" onclick="(function(){const z=+$('#nz').value;if(!z)return toast('Enter a zone number');AD.zoneMenu(z)})()">${ic('plus','s')} Add or move a zone</button></div>`)},
 zoneMenu(z){const v=coverage(z),H=housesByZone()[z];sheet(`<div class="row sp"><h2 class="title" style="font-size:22px">Zone <span class="zplate num" style="display:inline-grid;vertical-align:middle">${z}</span></h2><button class="ib flat" onclick="AD.combine()" aria-label="Back">${ic('x')}</button></div>
  <p class="sub sm mt8">${H?H.houses+' houses, '+H.cust+' customers ('+esc(H.areas.join(', '))+')':'No customers yet'}. Now: ${v.ok?v.r.code+' '+esc(v.r.name):esc(v.why)}.</p>
  ${D().rdefs.map((rd,i)=>`<button class="opt ${v.ok&&v.r.code===rd.code?'on':''}" onclick="AD.moveZone(${z},'${rd.code}')"><span><span class="rcode">${rd.code}</span>${esc(rd.name)}</span>${v.ok&&v.r.code===rd.code?ic('check'):''}</button>`).join('')}
  ${D().excl.map((e,i)=>`<button class="opt ${!v.ok&&v.why===e.label?'on':''}" onclick="AD.moveZone(${z},'x${i}')"><span style="color:var(--rose-i)">${ic('alert','s')} ${esc(e.label)}</span></button>`).join('')}`)},
 moveZone(z,to){D().rdefs.forEach(r=>r.zones=r.zones.filter(x=>x!==z));D().excl.forEach(e=>e.zones=e.zones.filter(x=>x!==z));
  let lab;if(to[0]==='x'){const e=D().excl[+to.slice(1)];e.zones.push(z);e.zones.sort((a,b)=>a-b);lab=e.label}else{const r=D().rdefs.find(r=>r.code===to);r.zones.push(z);r.zones.sort((a,b)=>a-b);lab=r.code}
  audit('Zone '+z+' moved to '+lab);save();toast('Zone '+z+' moved to '+lab);AD.combine()},
 stopDet(id){const {s,r}=findStop(id),c=cust(s.cid);sheet(`<div class="row sp"><h2 class="title" style="font-size:22px">${esc(c.name)}</h2><span class="pill tint-${s.status==='delivered'?'mint':'rose'}">${s.status}</span></div><div class="sub mt4">${esc(r.name)}, ${fmtD(r.date)}, stop ${s.seq}, ${esc(drv(r.driver).name)}</div>
  <div class="card mt16 tight">${s.status==='delivered'?`<div class="li"><span class="grow mute">Bottles delivered</span><b>${s.delivered}</b></div><div class="li"><span class="grow mute">Empties collected</span><b>${s.empties}</b></div><div class="li"><span class="grow mute">Reference</span><b>${s.ref}</b></div>`:`<div class="li"><span class="grow mute">Reason</span><b>${esc(s.miss_reason)}</b></div>`}<div class="li"><span class="grow mute">Time</span><b>${hm(s.completed_at)}</b></div>${s.gps?`<div class="li"><span class="grow mute">GPS</span><a class="b" style="color:var(--acc-i)" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${s.gps[0]},${s.gps[1]}">${s.gps[0]}, ${s.gps[1]}</a></div>`:''}</div>
  ${s.photo?`<img src="${s.photo}" alt="Proof photo" style="width:100%;border-radius:16px;display:block">`:'<div class="card flat c sub">No photo stored for this stop (seeded history).</div>'}
  <div class="two mt12"><button class="btn g" onclick="closeSheet()">Close</button><button class="btn t" onclick="AD.cdet('${c.id}')">Open customer</button></div>`)},
 /* --- Support --- */
 sup(){const l=D().tickets.filter(x=>S.a.f.t==='All'||x.status===S.a.f.t.toLowerCase().replace(' ','_')).sort((a,b)=>new Date(b.messages[b.messages.length-1].at)-new Date(a.messages[a.messages.length-1].at));const st={open:['sand','Open'],in_progress:['sky','In progress'],resolved:['mint','Resolved']};
  return AD.head('Support',openTickets().length+' open, replies reach the customer in their app and on WhatsApp')+
  `<div class="chips mb12">${['All','Open','In progress','Resolved'].map(z=>`<button class="chip ${S.a.f.t===z?'on':''}" onclick="S.a.f.t='${z}';render()">${z}</button>`).join('')}</div>
  <div class="card tight">${l.map(x=>{const last=x.messages[x.messages.length-1];return `<div class="li tap" onclick="AD.tkt('${x.id}')"><span class="avatar sm tint-sky">${initials(cust(x.cid).name)}</span><div class="grow" style="min-width:0"><div class="row sp"><b class="ell">${esc(x.subject)}</b><span class="sub xs" style="flex:none">${rel(last.at)}</span></div><div class="sub sm ell">${esc(cust(x.cid).name)}: ${esc(last.body)}</div></div><span class="pill tint-${st[x.status][0]}">${st[x.status][1]}</span></div>`}).join('')||'<div class="empty">No tickets here.</div>'}</div>`},
 tkt(id){const x=D().tickets.find(t=>t.id===id),c=cust(x.cid);const st={open:['sand','Open'],in_progress:['sky','In progress'],resolved:['mint','Resolved']};
  sheet(`<div class="row sp"><div><h2 class="title" style="font-size:20px">${esc(x.subject)}</h2><div class="sub mt4">${esc(c.name)}, ${esc(c.phone)}, ${zname(c)}</div></div><button class="ib flat" onclick="closeSheet(render)" aria-label="Close">${ic('x')}</button></div>
  <div class="seg mt12">${['open','in_progress','resolved'].map(s=>`<button class="${x.status===s?'on':''}" onclick="ACT.ticketStatus('${id}','${s}');AD.tkt('${id}')">${st[s][1]}</button>`).join('')}</div>
  <div class="card mt12" style="padding:6px 14px 14px">${x.messages.map(m=>`<div style="display:flex;justify-content:${m.from==='support'?'flex-end':'flex-start'};margin-top:8px"><div style="max-width:84%;padding:10px 14px;border-radius:18px;${m.from==='support'?'background:var(--ink);color:var(--bg);border-bottom-right-radius:6px':'background:var(--card2);border-bottom-left-radius:6px'}"><div>${esc(m.body)}</div><div class="xs mt4" style="opacity:.7">${m.from==='support'?'Support':c.name.split(' ')[0]}, ${fmtDay(m.at)} ${hm(m.at)}</div></div></div>`).join('')}</div>
  <div class="row"><input class="in grow" id="tr" placeholder="Reply to ${esc(c.name.split(' ')[0])}" onkeydown="if(event.key==='Enter')AD.sendReply('${id}')"><button class="btn p" onclick="AD.sendReply('${id}')">${ic('send')}</button></div>
  <div class="row mt12 wrap" style="gap:8px"><button class="btn sm g" onclick="$('#tr').value='Thanks for letting us know. We are looking into it and will update you today.'">Acknowledge</button><button class="btn sm g" onclick="$('#tr').value='Sorry about this. We have added 2 goodwill coupons to your balance.'">Goodwill</button><a class="btn sm g" href="https://wa.me/${c.phone.replace(/\D/g,'')}" target="_blank" rel="noopener">${ic('wa','s')} WhatsApp</a><button class="btn sm g" onclick="AD.cdet('${c.id}')">Customer</button></div>`,{focus:true})},
 sendReply(id){const v=$('#tr').value.trim();if(!v)return;ACT.reply(id,'support',v);if(/goodwill coupons/i.test(v)&&AD.isAdmin()){const t=D().tickets.find(t=>t.id===id);ACT.adjust(t.cid,2,'Goodwill for ticket')}toast('Reply sent');AD.tkt(id)},
 /* --- Reports --- */
 rep(){const m0=monthStart(),L=D().ledger.filter(e=>new Date(e.at)>=m0),del=L.filter(e=>e.kind==='delivered'),miss=L.filter(e=>e.kind==='missed'),sold=L.filter(e=>e.kind==='topup'&&e.amount);
  const n=S.a.repRange;const days=[];for(let i=n-1;i>=0;i--){const d=addDays(TODAY,-i),ds=ymd(d);days.push({d,del:D().ledger.filter(e=>e.kind==='delivered'&&e.at.slice(0,10)===ds).length,miss:D().ledger.filter(e=>e.kind==='missed'&&e.at.slice(0,10)===ds).length})}const mx=Math.max(1,...days.map(x=>x.del+x.miss));
  const zrows=[...D().rdefs.map(rd=>({rd,cs:D().customers.filter(c=>(routeOf(c)||{}).code===rd.code)})),{rd:null,cs:D().customers.filter(c=>!routeOf(c))}].map(({rd,cs})=>{const ids=cs.map(c=>c.id);return {rd,n:cs.length,del:del.filter(e=>ids.includes(e.cid)).length,bot:-sum(del.filter(e=>ids.includes(e.cid)),e=>e.coupons),miss:miss.filter(e=>ids.includes(e.cid)).length,low:cs.filter(c=>bal(c.id)<=D().settings.lowAt).length}}).filter(r=>r.rd||r.n);
  return AD.head('Reports',TODAY.toLocaleDateString('en-GB',{month:'long',year:'numeric'})+' to date',`<button class="btn g" onclick="AD.csv('customers')">${ic('download','s')} Customers</button><button class="btn g" onclick="AD.csv('deliveries')">${ic('download','s')} Deliveries</button><button class="btn g" onclick="AD.csv('ledger')">${ic('download','s')} Coupon ledger</button>`)+
  `<div class="kpis"><div class="kpi"><span class="ki tint-mint">${ic('check','s')}</span><div class="v num">${del.length}</div><div class="l">Deliveries</div></div><div class="kpi"><span class="ki tint-sky">${ic('drop','s')}</span><div class="v num">${-sum(del,e=>e.coupons)}</div><div class="l">Bottles</div></div><div class="kpi"><span class="ki tint-rose">${ic('alert','s')}</span><div class="v num" style="color:${miss.length?'var(--rose-i)':'inherit'}">${miss.length}</div><div class="l">Missed ${del.length+miss.length?Math.round(miss.length/(del.length+miss.length)*100):0}%</div></div><div class="kpi"><span class="ki tint-mint">${ic('card','s')}</span><div class="v num">${kfmt(sum(sold,e=>e.amount))}</div><div class="l">Revenue ${D().settings.currency}</div></div></div>
  <div class="card"><div class="row sp"><b class="h3">Deliveries per day</b><div class="seg" style="padding:3px">${[7,14,30].map(k=>`<button class="${n===k?'on':''}" style="padding:6px 12px" onclick="S.a.repRange=${k};render()">${k} days</button>`).join('')}</div></div>
   <div class="spark mt16" style="height:160px">${days.map((x,i)=>`<div class="${i===days.length-1?'on':''}" title="${fmtD(x.d)}: ${x.del} delivered, ${x.miss} missed"><div style="width:100%;display:flex;flex-direction:column;justify-content:flex-end;height:120px;gap:2px">${x.miss?`<i class="m" style="height:${x.miss/mx*100}%;flex:none;border-radius:6px 6px 0 0"></i>`:''}<i style="height:${Math.max(2,x.del/mx*100)}%;flex:none;border-radius:${x.miss?'0 0 4px 4px':'6px 6px 4px 4px'}"></i></div><span>${n>14&&i%3?'':x.d.getDate()}</span></div>`).join('')}</div>
   <div class="row mt8 xs mute" style="gap:14px"><span class="row" style="gap:6px"><i class="dot" style="background:var(--acc)"></i>Delivered</span><span class="row" style="gap:6px"><i class="dot" style="background:var(--rose-i)"></i>Missed</span></div></div>
  <div class="card"><b class="h3">By route this month</b><table class="tbl mt8"><thead><tr><th>Route</th><th>Driver</th><th>Customers</th><th>Deliveries</th><th>Bottles</th><th>Missed</th><th>Low on coupons</th></tr></thead><tbody>${zrows.map(r=>`<tr><td><b>${r.rd?r.rd.code+' '+esc(r.rd.name):'Out of zone'}</b></td><td class="hide-m">${r.rd&&r.rd.driver?esc(drv(r.rd.driver).name):'—'}</td><td class="num">${r.n} customers</td><td class="num">${r.del} deliveries</td><td class="num hide-m">${r.bot}</td><td class="num">${r.miss?`<span class="pill tint-rose">${r.miss}</span>`:'0'} missed</td><td class="num">${r.low?`<span class="pill tint-sand">${r.low}</span>`:'0'} low</td></tr>`).join('')}</tbody></table></div>`},
 csv(kind){let rows,name;const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
  if(kind==='customers'){name='customers.csv';rows=D().customers.map(c=>({id:c.no,name:c.name,phone:c.phone,email:c.email,status:c.status,zone:zname(c),zone_no:c.qzone,street_no:c.qstreet,building_no:c.qbuilding,building:c.building,street:c.street,delivery_day:DAYS[c.weekday],window:c.ws+'-'+c.we,bottles:c.bottles,coupons_left:bal(c.id),avg_monthly_use:avgMonthly(c.id),days_of_cover:daysLeft(c.id)??'',empties_with_customer:c.empties,lat:c.lat,lng:c.lng}))}
  else if(kind==='deliveries'){name='deliveries.csv';rows=D().ledger.filter(e=>(e.kind==='delivered'||e.kind==='missed')&&new Date(e.at)>=monthStart()).sort((a,b)=>new Date(a.at)-new Date(b.at)).map(e=>({date:e.at.slice(0,10),time:hm(e.at),customer:cust(e.cid).name,phone:cust(e.cid).phone,zone:zname(cust(e.cid)),status:e.kind,bottles:e.bottles||0,empties:e.empties||0,ref:e.ref||'',reason:e.detail||'',driver:e.driver?drv(e.driver).name:''}))}
  else{name='coupon-ledger.csv';rows=D().ledger.slice().sort((a,b)=>new Date(a.at)-new Date(b.at)).map(e=>({date:e.at.slice(0,10),time:hm(e.at),customer:cust(e.cid).name,type:e.adjust?'adjustment':e.kind,coupons:e.coupons,amount:e.amount??'',detail:e.detail||e.ref||''}))}
  const k=Object.keys(rows[0]||{}),txt=[k.join(','),...rows.map(r=>k.map(c=>q(r[c])).join(','))].join('\n');
  sheet(`<div class="row sp"><h2 class="title" style="font-size:22px">${name}</h2><span class="pill tint-grey">${rows.length} rows</span></div><p class="sub mt4">Opens in Excel or Google Sheets.</p><textarea class="in mt12" readonly style="height:200px;font-size:12px;font-family:ui-monospace,monospace;white-space:pre">${esc(txt)}</textarea>
  <div class="two mt12"><button class="btn g" onclick="AD.copyCsv(this)">${ic('copy','s')} Copy</button><button class="btn p" onclick="AD.dlCsv('${name}')">${ic('download','s')} Download</button></div>`);AD._csv=txt},
 copyCsv(b){const ta=$('#dim textarea');ta.select();try{navigator.clipboard.writeText(AD._csv).then(()=>toast('Copied'),()=>{document.execCommand('copy');toast('Copied')})}catch(e){try{document.execCommand('copy');toast('Copied')}catch(x){toast('Select the text and copy it')}}},
 dlCsv(name){try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+AD._csv],{type:'text/csv'}));a.download=name;document.body.appendChild(a);a.click();a.remove();toast('Downloading '+name+'. If nothing happens here, use Copy.')}catch(e){toast('Download blocked in this preview. Use Copy.')}},
 /* --- Settings --- */
 set(){const s=D().settings;const inp=(k,lab,type)=>`<label class="field"><span>${lab}</span><input class="in" type="${type||'text'}" value="${esc(s[k])}" onchange="D().settings['${k}']=${type==='number'?'+':''}this.value;save();applyTheme();toast('Saved');render()"></label>`;
  return AD.head('Settings','White-label the apps for your company. Changes apply everywhere immediately.')+
  `<div class="cols"><div><div class="card"><b class="h3">Brand</b>${inp('company','Company name shown in all three apps')}<div class="field"><span>Accent colour</span><div class="row" style="gap:12px">${Object.entries(ACCENTS).map(([k,v])=>`<button class="swatch ${s.accent===k?'on':''}" style="background:${v}" title="${k}" onclick="D().settings.accent='${k}';save();applyTheme();render()"></button>`).join('')}</div></div>${inp('currency','Currency code')}</div>
   <div class="card"><b class="h3">Support contact</b>${inp('supportPhone','Phone shown to customers')}${inp('supportWa','WhatsApp number')}</div>
   <div class="card"><b class="h3">Coupon rules</b><div class="two">${inp('warnAt','"Running low" at or below','number')}${inp('lowAt','"Low" alert at or below','number')}</div>${inp('holdMax','Maximum hold, days','number')}</div></div>
  <div><div class="card"><div class="row sp"><b class="h3">Coupon packs</b><button class="btn sm g" onclick="D().packs.push({id:'p'+uid(),coupons:90,price:600});save();render()">${ic('plus','s')} Add pack</button></div><table class="tbl mt8"><thead><tr><th>Coupons</th><th>Price</th><th>Per bottle</th><th></th></tr></thead><tbody>${D().packs.map(p=>`<tr><td><input class="in" type="number" value="${p.coupons}" style="width:90px;padding:8px 10px" onchange="(function(v){const p=D().packs.find(x=>x.id==='${p.id}');p.coupons=+v||p.coupons;save();render()})(this.value)"></td><td><input class="in" type="number" value="${p.price}" style="width:100px;padding:8px 10px" onchange="(function(v){const p=D().packs.find(x=>x.id==='${p.id}');p.price=+v||p.price;save();render()})(this.value)"></td><td class="num hide-m">${(p.price/p.coupons).toFixed(2)}</td><td style="text-align:end">${D().packs.length>1?`<button class="ib flat" onclick="D().packs=D().packs.filter(x=>x.id!=='${p.id}');save();render()" aria-label="Remove">${ic('x','s')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>
   <div class="card"><div class="row sp"><b class="h3">Delivery routes</b><button class="btn sm g" onclick="AD.combine()">Edit</button></div><div class="mt4">${D().rdefs.map(r=>`<div class="li"><span class="rcode">${r.code}</span><span class="grow">${esc(r.name)}<div class="sub xs">Zones ${r.zones.join(', ')}</div></span><b class="sm">${r.driver?esc(drv(r.driver).name.split(' ')[0]):'—'}</b></div>`).join('')}<div class="li"><span class="grow sub sm">Excluded zones: ${D().excl.flatMap(e=>e.zones).join(', ')}</span></div></div></div>
   <div class="card"><b class="h3">Team</b>${D().staff.map(x=>`<div class="li"><span class="avatar sm tint-acc">${initials(x.name)}</span><div class="grow"><b>${esc(x.name)}</b><div class="sub xs">${esc(x.email)}</div></div><span class="pill tint-${x.role==='admin'?'lilac':'grey'}">${x.role}</span></div>`).join('')}<p class="sub sm mt8">Admins can adjust coupons and manage drivers. Support can do everything else.</p></div>
   <div class="card"><b class="h3">Activity log</b><div class="feed mt12">${D().audit.slice(0,8).map(a=>`<div class="li"><div class="grow"><div class="sm">${esc(a.who)} ${esc(a.what.charAt(0).toLowerCase()+a.what.slice(1))}</div><div class="xs mute">${fmtD(a.at)}, ${hm(a.at)}</div></div></div>`).join('')}</div></div>
   <div class="card"><b class="h3">Demo</b><p class="sub sm mt4">Sample data regenerates for the current date. Reset puts everything back, including anything you changed here.</p><div class="row mt12"><button class="btn g" onclick="toggleTheme()">${ic('moon','s')} Switch theme</button><button class="btn d" onclick="resetDemo()">${ic('refresh','s')} Reset demo data</button></div></div></div></div>`},
 more(){return AD.head('More')+`<div class="card tight">${[['drv','truck','Drivers','Vehicles, zones and progress'],['rep','chart','Reports','Monthly numbers and exports'],['set','sliders','Settings','Brand, packs, zones, team']].map(n=>`<div class="li tap" onclick="AD.go('${n[0]}')"><span class="ic tint-grey">${ic(n[1])}</span><div class="grow"><b>${n[2]}</b><div class="sub sm">${n[3]}</div></div>${ic('right')}</div>`).join('')}</div>
  <div class="card tight"><div class="li tap" onclick="AD.preview('driver')"><span class="ic tint-mint">${ic('phone')}</span><div class="grow"><b>Driver app</b><div class="sub sm">See what a driver sees today</div></div>${ic('right')}</div><div class="li tap" onclick="AD.preview('customer')"><span class="ic tint-sky">${ic('phone')}</span><div class="grow"><b>Customer app</b><div class="sub sm">Open any customer's app</div></div>${ic('right')}</div></div>
  <div class="card tight"><div class="li tap" onclick="toggleTheme()"><span class="ic tint-grey">${ic('moon')}</span><span class="grow b">Switch light / dark</span></div><div class="li tap" onclick="signOut()"><span class="ic tint-rose">${ic('logout')}</span><span class="grow b">Sign out</span><span class="sub sm">${esc(S.me.name)}</span></div></div>`}
};
